INSERT INTO `creatives` (`id`, `title`, `description`, `url`, `image_url`) VALUES
(1, 'Beating the Heat: Keeping Students Learning Through the Bangladeshi Summer', 'Bangladesh\'s intense summer heat disrupts student learning. Schools can ease this with adjusted schedules and heat safety measures to help students focus and stay comfortable.', 'https://cub.edu.bd/creatives_post.php?title=Beating-the-Heat-Keeping-Students-Learning-Through-the-Bangladeshi-Summer', 'creatives\\Beating_the_Heat_Keeping_Students_Learning_Throug.jpg'),
(2, 'নারী ক্ষমতায়নের প্রধান বাধা আজ নারী নিরাপত্তা', '২০২৫ সালের নারী দিবসের প্রতিপাদ্য \"অ্যাকশন ত্বরান্বিত করুন\"। নারীর নিরাপত্তা, সমতা ও অগ্রগতির লক্ষ্যে এগিয়ে চলার আহ্বান, যাতে তারা পূর্ণ সম্ভাবনা বিকাশ করতে পারে।', 'https://cub.edu.bd/creatives_post.php?title=Womens-safety-is-the-main-obstacle-to-womens-empowerment-today', 'creatives\\নারী_ক্ষমতায়নের_প্রধান_বাধা_আজ_নারী_নিরাপত্তা.jpg'),
(3, 'North American Standard Education at Canadian University of Bangladesh', 'Experience the pinnacle of education with North American standard education at Canadian University of Bangladesh. Elevate your academic journey today.', 'https://cub.edu.bd/creatives_post.php?title=North-American-Standard-Education-at-Canadian-University-of-Bangladesh', 'creatives\\North_American_Standard_Education_at_Canadian_Univ.jpg'),
(4, 'Experienced and Knowledgeable Faculty at Canadian University of Bangladesh', 'Elevate your educational experience with the expertise of Canadian University of Bangladesh\'s experienced and knowledgeable faculty. Learn from the best, excel in your studies.', 'https://cub.edu.bd/creatives_post.php?title=Experienced-and-Knowledgeable-Faculty-at-Canadian-University-of-Bangladesh', 'creatives\\Experienced_and_Knowledgeable_Faculty_at_Canadian_.jpg'),
(5, 'Emotions and Relationships', 'This captivating story, penned by Ummey Mehenaj, a student at the Canadian University of Bangladesh (CUB), delves into the intricacies of human emotions and relationships.', 'https://cub.edu.bd/creatives_post.php?title=Emotions-and-Relationships', 'creatives\\Emotions_and_Relationships.jpg'),
(6, 'ফুলচাষী', '“ফুলচাষী” কবিতাটি লিখেছেন ফয়সাল জামান অলীক। তিনি কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশ এর মিডিয়া কমিউনিকেশন এন্ড জার্নালিজম বিভাগের শিক্ষার্থী।', 'https://cub.edu.bd/creatives_post.php?title=ফুলচাষী', 'creatives\\ফুলচাষী.png'),
(7, 'Bridging Education: Job Placement Opportunities at Canadian University of Bangladesh', 'Unlock your career potential with Canadian University of Bangladesh\'s job placement opportunities. Bridging education and employment for a brighter future.', 'https://cub.edu.bd/creatives_post.php?title=Bridging-Education-Job-Placement-Opportunities-at-Canadian-University-of-Bangladesh', 'creatives\\Bridging_Education_Job_Placement_Opportunities_at.jpg'),
(8, 'Empowering Dreams: Scholarship Opportunities at Canadian University of Bangladesh', 'Discover limitless possibilities with Canadian University of Bangladesh\'s unmatched scholarships. Empower your dreams today.', 'https://cub.edu.bd/creatives_post.php?title=Empowering-Dreams-Scholarship-Opportunities-at-Canadian-University-of-Bangladesh', 'creatives\\Empowering_Dreams_Scholarship_Opportunities_at_Ca.jpg'),
(9, 'Enriching Student Life: Diverse Extracurricular Activities at CUB', 'Experience an enriched student life with diverse extracurricular activities at Canadian University of Bangladesh. From clubs to sports, unleash your potential beyond academics.\"', 'https://cub.edu.bd/creatives_post.php?title=adfg', 'creatives\\Enriching_Student_Life_Diverse_Extracurricular_Ac.jpg'),
(10, 'Empowering Success: Career Development Support at Canadian University of Bangladesh', 'Empower your journey to success with personalized attention and robust career development support at Canadian University of Bangladesh. Realize your potential, achieve greatness.', 'https://cub.edu.bd/creatives_post.php?title=sfdhgh', 'creatives\\Empowering_Success_Career_Development_Support_at_.jpg'),
(11, 'Study Abroad: Credit Transfer Facilities at Canadian University of Bangladesh', 'Embark on a global academic journey with Canadian University of Bangladesh\'s international credit transfer facilities. Expand your horizons and reach new heights.', 'https://cub.edu.bd/creatives_post.php?title=Study-Abroad-Credit-Transfer-Facilities-at-Canadian-University-of-Bangladesh', 'creatives\\Study_Abroad_Credit_Transfer_Facilities_at_Canadi.jpg'),
(12, 'Embracing Innovation: Modern and Digitalized Campus of Canadian University of Bangladesh', 'Step into the future of education at Canadian University of Bangladesh\'s modern, digitalized City Campus. Embrace innovation and redefine your academic experience.', 'https://cub.edu.bd/creatives_post.php?title=Embracing-Innovation-Modern-and-Digitalized-Campus-of-Canadian-University-of-Bangladesh', 'creatives\\Embracing_Innovation_Modern_and_Digitalized_Campu.jpg'),
(13, 'Dusk\'s Embrace', 'The poem, penned by CUB student Ilhan Hossain, envisions a future devoid of sorrow, where one attains inner beauty. Patience is advocated until that day arrives.', 'https://cub.edu.bd/creatives_post.php?title=Dusk-s-Embrace', 'creatives\\Dusk\'s_Embrace.jpg'),
(14, 'Agonizing artistry!', 'The poem depicts how art helps the speaker cope with adversity. Despite feeling belittled, they draw on past resilience. It was written by Rizwan ullah, a CUB\'S BBA student.', 'https://cub.edu.bd/creatives_post.php?title=Agonizing-artistry', 'creatives\\Agonizing_artistry!.jpg'),
(15, 'Desperation', '\"Desperation\" is a poignant poem that delves into the feeling of being trapped and longing for freedom and joy. This poem is written by Rizwanullah Shuvo.', 'https://cub.edu.bd/creatives_post.php?title=Desperation', 'creatives\\Desperation.jpg'),
(16, 'Reasons why I do it?', 'This poem reflects the profound motivations and aspirations of a writer. Rizwan Ullah Shuvo, a Canadian University of Bangladesh student, wrote the poem.', 'https://cub.edu.bd/creatives_post.php?title=Reasons-why-I-do-it', 'creatives\\Reasons_why_I_do_it.jpg'),
(17, 'আজকের, দৈনিক দুর্দিন রিপোর্টার : বিষাদ কাব্য', '\"আজকের, দৈনিক দুর্দিন, রিপোর্টার: বিষাদ কাব্য।\" কবিতাটি লিখেছেন কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশ এর মিডিয়া কমিউনিকেশন এন্ড জার্নালিজম বিভাগের শিক্ষার্থী ফয়সাল জামান অলিক।', 'https://cub.edu.bd/creatives_post.php?title=আজকের-দৈনিক-দুর্দিন-রিপোর্টার-বিষাদ-কাব্য', 'creatives\\আজকের,_দৈনিক_দুর্দিন_রিপোর্টার__বিষাদ_কাব্য.jpg'),
(18, 'আমাদের সবার বাংলাদেশ', 'দেশপ্রেমকে জাগিয়ে তুলতে দেশের জন্যে কবিতা লিখেছেন ব্যবসা অনুষদ বিভাগের বিভাগীয় প্রধান এস এম আরিফুজ্জামান। কবিতার নাম  “আমাদের সবার বাংলাদেশ”।', 'https://cub.edu.bd/creatives_post.php?title=আমাদের-সবার-বাংলাদেশ', 'creatives\\আমাদের_সবার_বাংলাদেশ.jpg'),
(19, 'Systematically Caged', '\"Systematically caged\" is a poem that critiques the educational system and societal norms. The poem was written by Rijwan Ulllah, a student of Canadian University of Bangladesh.', 'https://cub.edu.bd/creatives_post.php?title=Systematically-Caged', 'creatives\\Systematically_Caged.jpg'),
(20, 'Ephemeral Bliss', 'The poem \'Ephemeral Bliss\' was written by Ilhan Hussein, a student of Canadian University of Bangladesh.', 'https://cub.edu.bd/creatives_post.php?title=Ephemeral-Bliss', 'creatives\\Ephemeral_Bliss.jpg'),
(21, 'বিদায়', 'বিদায় ছোট গল্পটি লিখেছেন কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশের ব্যবসা অনুষদ বিভাগের শিক্ষার্থী রিজওয়ান উল্লাহ শুভ।', 'https://cub.edu.bd/creatives_post.php?title=বিদায়', 'creatives\\বিদায়.jpg'),
(22, 'অজ্ঞাত এবং অভিশপ্ত', 'অজ্ঞাত এবং অভিশপ্ত ছোট গল্পটি লিখেছেন কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশের ব্যবসা অনুষদ বিভাগের শিক্ষার্থী মো. রুহুল আমিন।', 'https://cub.edu.bd/creatives_post.php?title=অজ্ঞাত-এবং-অভিশপ্ত', 'creatives\\অজ্ঞাত_এবং_অভিশপ্ত.jpg'),
(23, 'কবিতা', 'কবিতা নামের কবিতাটি লিখেছেন রিজওয়া উল্লাহ শুভ। রিজওয়ান কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশের ব্যবসা অনুষদ বিভাগের চতুর্থ বর্ষের শিক্ষার্থী।', 'https://cub.edu.bd/creatives_post.php?title=কবিতা', 'creatives\\কবিতা.jpg'),
(24, 'একদিন গোধূলির বেলায়', 'একদিন গোধূলির বেলায় কবিতাটি লিখেছেন কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশ এর শিক্ষার্থী রিজওয়ানউল্লাহ শুভ।', 'https://cub.edu.bd/creatives_post.php?title=একদিন-গোধূলির-বেলায়', 'creatives\\একদিন_গোধূলির_বেলায়.jpg'),
(25, 'My Heart Was Lost To Me', 'The poem ‘My Heart Was Lost To Me\' has been written by Ilhan Hussein, a tutee, of Canadian University Of Bangladesh, from the department of English.', 'https://cub.edu.bd/creatives_post.php?title=My-Heart-Was-Lost-To-Me', 'creatives\\My_Heart_Was_Lost_To_Me.jpg'),
(26, 'কবিতার নাম ’পুরান ঢাকা’', 'পুরান ঢাকার ঐতিয্য নিয়ে ”পুরান ঢাকা” কবিতাটি লিখেছেন মো. রিজওয়ান উল্লাহ শুভ। তিনি কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ ব্যাবসায় অনুষদ বিভাগের শিক্ষার্থী।', 'https://cub.edu.bd/creatives_post.php?title=কবিতার-নাম-পুরান-ঢাকা', 'creatives\\কবিতার_নাম_’পুরান_ঢাকা’.jpg'),
(27, 'Memories of Childhood', 'Childhood is a period where we truly live, free from all burden and tension. “Memories of Childhood” the poem has been rhymed by MD. Rizwan Ullah Shuvo from the department of BBA.', 'https://cub.edu.bd/creatives_post.php?title=Memories-of-Childhood', 'creatives\\Memories_of_Childhood.jpg'),
(28, 'Canadian University of Bangladesh: Nurturing Minds and Igniting Possibilities', 'The poem has been written upon Canadian University of Bangladesh by Nawshin Nawar Sushi, a student from BBA department of the university.', 'https://cub.edu.bd/creatives_post.php?title=Canadian-University-of-Bangladesh-Nurturing-Minds-and-Igniting-Possibilities', 'creatives\\Canadian_University_of_Bangladesh_Nurturing_Minds.jpg'),
(29, 'Beast: Escaping Dimensions, Defeating Spirituality', 'From the forbidden part of the Library, Yunny finds a perplexing book which brings her, spiritual fortune to discover a mysterious beast and two unworldly figures, Mary and Felix.', 'https://cub.edu.bd/creatives_post.php?title=Beast-Escaping-Dimensions-Defeating-Spirituality', 'creatives\\Beast_Escaping_Dimensions,_Defeating_Spirituality.jpg'),
(30, 'OLD SCHOOL DAYS', '“OLD SCHOOL DAYS” the poem has been rhymed by MD Rizwan Ullah Shuvo, a pupil of BBA department. School days brings the most precious moments & friendship in our life.', 'https://cub.edu.bd/creatives_post.php?title=OLD-SCHOOL-DAYS', 'creatives\\OLD_SCHOOL_DAYS.JPG'),
(31, 'কবিতার নাম “ডুবি!”', '‘ডুবি’ কবিতাটি লিখেছেন কানাডিয়ান বিশ্ববিদ্যালয় অব বাংলাদেশের মিডিয়া কমিউনিকেশন এন্ড জার্নালিজম বিভাগের কৃতি শিক্ষার্থী ফয়সাল জামান অলীক।', 'https://cub.edu.bd/creatives_post.php?title=কবিতার-নাম-ডুবি', 'creatives\\কবিতার_নাম_“ডুবি!”.jpg');
INSERT INTO `events` (`id`, `title`, `description`, `url`, `image_url`, `date`, `time`) VALUES
(1, 'Maritime Entrepreneurship Seminar: Opportunities & Challenges Ahead', 'Join industry leaders at CUB for insights on maritime entrepreneurship-discover future opportunities, overcome challenges, and gain expert guidance.', '', 'events\\2025-08-25_Maritime_Entrepreneurship_Seminar_Opportunities_&.jpg', '2025-08-25', '03:30 PM'),
(2, 'Maritime Seminar Towards a Sustainable Future', 'This seminar will offer valuable insights into cutting-edge developments in autonomous maritime systems, Ship recycling and alternative marine fuel.', '', 'events\\2025-05-04_Maritime_Seminar_Towards_a_Sustainable_Future.png', '2025-05-04', '03:00 PM'),
(3, 'CSE Iftar Mahfil – A Gathering of Blessings & Togetherness at Canadian University of Bangladesh', 'The CSE Department of CUB arranged a special Iftar Mahfil, uniting students, faculty, and alumni in a warm and spiritual gathering during the sacred month of Ramadan.', '', 'events\\2025-03-22_CSE_Iftar_Mahfil_–_A_Gathering_of_Blessings_&_Toge.jpg', '2025-03-22', '06:00 PM'),
(4, 'MCJ Iftar Mahfil 2025: An Evening of Blessings, Togetherness, and Reflection!', 'The MCJ Department hosted its annual Iftar Mahfil on March 15, 2025 creating a heartfelt gathering of faculty members, students & esteemed guests.', '', 'events\\2025-03-15_MCJ_Iftar_Mahfil_2025_An_Evening_of_Blessings,_To.jpg', '2025-03-15', '06:43 PM'),
(5, '10K LEGATHON - CUB Law Mini-Marathon 2025', 'On February 27, 2025, Department of Law of Canadian University of Bangladesh arranged a mini-marathon \"10K Legathon\" for the first time!', '', 'events\\2025-02-27_10K_LEGATHON_-_CUB_Law_Mini-Marathon_2025.jpg', '2025-02-27', '10:00 AM'),
(6, 'International Women\'s Day 2025 at Canadian University of Bangladesh!', 'Canadian University of Bangladesh celebrated Women\'s Day with inspiring speeches & expert talks on mental health, nutrition & yoga. Empowering women for a healthier future!', '', 'events\\2025-03-07_International_Women\'s_Day_2025_at_Canadian_Univers.jpg', '2025-03-07', '10:00 AM'),
(7, 'Workshop on Bangladesh National Qualifications Framework (BNQF)', 'The Institutional Quality Assurance Cell (IQAC) of CUB successfully hosted a workshop on BNQF on 09th November, 2024 at the CUB Auditorium.', '', 'events\\2024-11-09_Workshop_on_Bangladesh_National_Qualifications_Fra.png', '2024-11-09', '03:00 PM'),
(8, 'Impact of Due Diligence in Maintaining Corporate Governance” held at CUB', 'Canadian University of Bangladesh organized a seminar titled “The Impact of Due Diligence in Maintaining Corporate Governance” on Thursday, January 4, 2024, at its Auditorium.', '', 'events\\2024-01-04_Impact_of_Due_Diligence_in_Maintaining_Corporate_G.jpg', '2024-01-04', '04:00 PM'),
(9, 'Students from Canadian University of Bangladesh have visited Southeast Bank', 'January 04, 2024 – Today, the Department of School of Business of the Canadian University of Bangladesh successfully organized a Study Tour to the Southeast Bank PLC Head Office.', '', 'events\\2024-01-04_Students_from_Canadian_University_of_Bangladesh_ha.jpg', '2024-01-04', '12:00 PM'),
(10, 'First-ever class at the permanent campus of the Canadian University of Bangladesh.', 'The Canadian University of Bangladesh achieved a historic milestone on January 3, 2024, by conducting its first-ever class at the permanent campus located at Purbachal, Dhaka.', '', 'events\\2024-01-03_First-ever_class_at_the_permanent_campus_of_the_Ca.jpg', '2024-01-03', '11:00 AM'),
(11, 'Book on “Essentials of Internet Banking” Unveiled at CUB', 'Unveiling ceremony of the book “Essentials of Internet Banking” was held on 3rd January 2024 at the auditorium of the Canadian University of Bangladesh written by CUB professors.', '', 'events\\2024-01-03_Book_on_“Essentials_of_Internet_Banking”_Unveiled_.jpg', '2024-01-03', '12:00 PM'),
(12, 'MCJ Department Orchestrates Enlightening Study Tour to Dainik Bangla', 'Dhaka, January 02, 2024 – Today, the MCJ Department of Canadian University of Bangladesh (CUB) successfully organized a Study Tour to Dainik Bangla.', '', 'events\\2024-01-02_MCJ_Department_Orchestrates_Enlightening_Study_Tou.jpg', '2024-01-02', '11:00 AM'),
(13, 'An enlightening Study Tour was organized at Padma Bank', 'Canadian University of Bangladesh has organized a Study Tour to Padma Bank Ltd for its students. School of Business was the host Department for arranging the tour.', '', 'events\\2024-01-01_An_enlightening_Study_Tour_was_organized_at_Padma_.jpg', '2024-01-01', '11:00 AM'),
(14, 'EEE Dept. of CUB made a study tour at Unique Meghnaghat Power-plant Limited (UMPL)', 'Students from the Canadian University of Bangladesh had an exciting study tour at the Unique Meghnaghat Power-plant Limited (UMPL) on December 28, 2023.', '', 'events\\2023-12-28_EEE_Dept._of_CUB_made_a_study_tour_at_Unique_Meghn.png', '2023-12-28', '12:30 PM'),
(15, 'A significant workshop on psychological disorders recently took place at the CUB', 'The significant workshop, titled \"Know Thyself: Understanding Mental Health” was organized at university\'s auditorium by CUB Mental Health Club in collaboration with the CUBBC.', '', 'events\\2023-12-28_A_significant_workshop_on_psychological_disorders_.png', '2023-12-28', '11:00 PM'),
(16, 'Closing Ceremony of ‘Dr. Chowdhury Nafeez Sarafat Merit Award Week 2023’', 'The closing ceremony of ‘Dr. Chowdhury Nafeez Sarafat Merit Award Week 2023’ was held on 20th December, 2023 in the auditorium of Canadian University of Bangladesh.', '', 'events\\2023-12-20_Closing_Ceremony_of_‘Dr._Chowdhury_Nafeez_Sarafat_.jpg', '2023-12-20', '03:00 PM'),
(17, 'Carpe Diem English Club Orientation Event at Canadian University of Bangladesh', 'The Department of English at the Canadian University of Bangladesh (CUB) hosted a dynamic orientation for the \'Carpe Diem English Club\' on 25th November 2023', '', 'events\\2023-11-25_Carpe_Diem_English_Club_Orientation_Event_at_Canad.jpg', '2023-11-25', '10:00 AM'),
(18, 'The Annual Debate Competition Successfully Held In CUB', 'The CUB Debating Society (CUBLDS) concluded its annual debate competition, CUBLDS 2nd Inter-Batch Debate Competition 2023, on November 4, 2023.', '', 'events\\2023-11-23_The_Annual_Debate_Competition_Successfully_Held_In.jpg', '2023-11-23', '10:00 AM'),
(19, 'Learning from the Best: A Stock Brokerage Firm Visit to UCB Stock Exchange!!', 'On 14 September 2023, the School of Business, CUB Business Club, and FIN-423 students organized a stock brokerage firm visit to the UCB stock exchange as a part of practical insights regarding coursework.', '', 'events\\2023-09-14_Learning_from_the_Best_A_Stock_Brokerage_Firm_Vis.jpg', '2023-09-14', '10:00 AM'),
(20, 'Feedback Program at CUB by EEE Department!', 'The EEE Department Student Feedback Program at Canadian University of Bangladesh (CUB) was a massive success.', '', 'events\\2023-09-12_Feedback_Program_at_CUB_by_EEE_Department!.jpg', '2023-09-12', '11:00 AM'),
(21, '\"Kickoff Programming Contest Fall-2023\" at CUB', 'CUB\'s CSE Department\'s programming contest, a success with balloons, competition, and distinguished guests, ignites global ambitions.', '', 'events\\2023-08-19_Kickoff_Programming_Contest_Fall-2023_at_CUB.jpg', '2023-08-19', '10:00 AM'),
(22, 'Banglalink Youth Fest 2023 at CUB', 'Banglalink Youth Fest 2023 at CUB with thrilling games, vibrant booths, and unforgettable memories!', '', 'events\\2023-08-16_Banglalink_Youth_Fest_2023_at_CUB.jpg', '2023-08-16', '10:00 AM'),
(23, 'Celebrating an Unforgettable Orientation Program at Canadian University of Bangladesh (CUB)!', 'The journey has began with the freshers of Summer\'23 Batch of CUB! With immense excitement and enthusiasm, they joined the dynamic orientation program, ready to embrace a world of opportunities and excellence.', '', 'events\\2023-07-25_Celebrating_an_Unforgettable_Orientation_Program_a.jpg', '2023-07-25', '02:30 PM'),
(24, 'Theater at CUB Auditorium by Carpe Diem Club', 'Eng Dept of CUB presents “The Tragic Fate of Medusa” with famous actor Riaz Ahmed at CUB Auditorium', '', 'events\\2023-05-16_Theater_at_CUB_Auditorium_by_Carpe_Diem_Club.jpg', '2023-05-16', '02:00 PM'),
(25, '1st Convocation of CUB', 'Chief Guest President Md. Abdul Hamid and Convocation Speaker Nobel Laureate Kailash Satyarthi.', '', 'events\\2023-01-31_1st_Convocation_of_CUB.jpg', '2023-01-31', '03:00 PM'),
(26, 'Open session on Meet the Masters held at CUB', 'Canadian University of Bangladesh organized a session Meet the Masters on Sunday at CUB auditorium.', '', 'events\\2023-01-21_Open_session_on_Meet_the_Masters_held_at_CUB.jpg', '2023-01-21', '03:00 PM'),
