(116, '2024-02-21', 'কেন্দ্রীয় শহিদ মিনারে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশের পুষ্পস্তবক অর্পণ', 'বুধবার (২১.০২.২০২৪), অমর একুশে আন্তর্জাতিক মাতৃভাষা দিবসে কেন্দ্রীয় শহিদ মিনার বেদিতে শ্রদ্ধা নিবেদন করে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ।', 'https://cub.edu.bd/news_post.php?title=canadian-university-of-bangladesh-lays-wreath-at-central-shaheed-minar', 'news\\2024-02-21_কেন্দ্রীয়_শহিদ_মিনারে_কানাডিয়ান_ইউনিভার্সিটি_অব_ব.jpg');
INSERT INTO `news` (`id`, `date`, `title`, `description`, `url`, `image_url`) VALUES
(117, '2024-02-19', 'বাংলাদেশে-এ দাবা প্রতিযোগিতায় চ্যাম্পিয়ন মাস্টার জগোদিস ‍সিদ্বার্থ', 'কানাডিয়ান ইউনির্ভাসিটি অব বাংলাদেশ, এল আর গ্লোবাল ও ফ্লোরা টেলিকম যৌথভাবে এল আর গ্লোবাল গ্র্যান্ড মাস্টার এসপিরেন্ট ১ দাবা প্রতিযোগিতার আয়োজন করে।', 'https://cub.edu.bd/news_post.php?title=master-jagodis-siddharth-is-the-champion-in-a-chess-competition-in-bangladesh', 'news\\2024-02-19_বাংলাদেশে-এ_দাবা_প্রতিযোগিতায়_চ্যাম্পিয়ন_মাস্টার_জ.jpg'),
(118, '2024-02-18', 'কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ-এ আইন বিভাগে ভর্তি চলছে', 'আইন বিভাগের এলএলবি (অনার্স) ডিগ্রির জন্য অত্যন্ত জনপ্রিয় কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ (সিইউবি)। সামার ২০২৪ সেশনে ভর্তি নিচ্ছে বিভাগটি।', 'https://cub.edu.bd/news_post.php?title=admissions-are-ongoing-in-the-law-department-at-the-canadian-university-of-bangladesh', 'news\\2024-02-18_কানাডিয়ান_ইউনিভার্সিটি_অব_বাংলাদেশ-এ_আইন_বিভাগে_ভর.jpg'),
(119, '2024-02-18', 'ভাষার মাসে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশে বিশেষ ওয়েভারে ভর্তি', 'অমর একুশে ফেব্রুয়ারি ২০২৪ উপলক্ষ্যে ভর্তি ফি এবং টিউশন ফির উপর বিশেষ ছাড়ে ভর্তি করছে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ। ১৯ থেকে ২৯ ফেব্রুয়ারি পর্যন্ত থাকবে এই বিশেষ সুযোগ।', 'https://cub.edu.bd/news_post.php?title=canadian-university-of-bangladesh-special-waiver-admissions-for-language-month', 'news\\2024-02-18_ভাষার_মাসে_কানাডিয়ান_ইউনিভার্সিটি_অব_বাংলাদেশে_বিশ.jpg'),
(120, '2024-02-17', 'ইউএমপিএল কে হারিয়ে সিইউবি’র প্রথম জয়', 'কর্পোরেট ক্রিকেট চ্যাম্পিয়নশীপ টুর্নামেন্ট-২৪ এর নিজেদের ৩য় ম্যাচে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ (সিইউবি)  মেঘনাঘাট পাওয়ার প্লান্ট লিমিটেড’কে ৭ রানে পরাজিত করে।', 'https://cub.edu.bd/news_post.php?title=cubs-first-win-by-defeating-umpl', 'news\\2024-02-17_ইউএমপিএল_কে_হারিয়ে_সিইউবি’র_প্রথম_জয়.jpg'),
(121, '2024-02-17', 'Workshop on \'Freelancing and Outsourcing\' held at Canadian University of Bangladesh', 'Canadian University of Bangladesh in collaboration with EduTech Consortium organized a workshop on \'Freelancing and Outsourcing\' on Saturday at its Rooftop venue', 'https://cub.edu.bd/news_post.php?title=Workshop-on-Freelancing-and-Outsourcing-held-at-Canadian-University-of-Bangladesh', 'news\\2024-02-17_Workshop_on_\'Freelancing_and_Outsourcing\'_held_at_.jpeg'),
(122, '2024-02-16', 'Message from the Pro-Vice Chancellor and VC (Acting) of Canadian University of Bangladesh', 'I am delighted to extend a warm welcome to you on behalf of the Canadian University of Bangladesh.', 'https://cub.edu.bd/news_post.php?title=Message-from-the-Pro-Vice-Chancellor-and-VC-Acting-of-Canadian-University-of-Bangladesh', 'news\\2024-02-16_Message_from_the_Pro-Vice_Chancellor_and_VC_(Actin.jpeg'),
(123, '2024-02-14', 'কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ-এ বসন্ত মেলা উদযাপন', 'উৎসবকে আনন্দমুখর করে তুলতে বিশ্ববিদ্যালয়ের ক্যাম্পাসে মেলার আয়োজন করে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ।', 'https://cub.edu.bd/news_post.php?title=spring-fair-celebrated-at-canadian-university-of-bangladesh', 'news\\2024-02-14_কানাডিয়ান_ইউনিভার্সিটি_অব_বাংলাদেশ-এ_বসন্ত_মেলা_উদ.jpg'),
(124, '2024-02-13', 'শতভাগ পর্যন্ত স্কলারশিপে ভর্তি কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ-এ', 'কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ দেশের স্বনামধন্য একটি উচ্চশিক্ষা প্রতিষ্ঠান। হাতিরঝিলের সন্নিকটে রাজধানীর প্রগতী সরণিতে বিশ্ববিদ্যালয়ের নিজস্ব ক্যাম্পাস অবস্থিত।', 'https://cub.edu.bd/news_post.php?title=full-scholarship-admission-canadian-university-of-bangladesh', 'news\\2024-02-13_শতভাগ_পর্যন্ত_স্কলারশিপে_ভর্তি_কানাডিয়ান_ইউনিভার্স.jpg'),
(125, '2024-02-13', 'Canadian University of Bangladesh Launches Medical Center', 'Dhaka, February 13, 2024; the Canadian University of Bangladesh proudly announced the inauguration of its Medical Center on the bustling second floor of its campus for students.', 'https://cub.edu.bd/news_post.php?title=Canadian-University-of-Bangladesh-Launches-Medical-Center', 'news\\2024-02-13_Canadian_University_of_Bangladesh_Launches_Medical.jpg'),
(126, '2024-02-10', 'EduTech Consortium Workshop on 3D Printing held at Canadian University of Bangladesh', 'Saturday, February 10, 2024 a workshop titled \"3D Printing with Ultimate Cura\" was officially launched at the Canadian University of Bangladesh (CUB)’s rooftop venue.', 'https://cub.edu.bd/news_post.php?title=EduTech-Consortium-Workshop-on-3D-Printing-held-at-Canadian-University-of-Bangladesh', 'news\\2024-02-10_EduTech_Consortium_Workshop_on_3D_Printing_held_at.jpg'),
(127, '2024-02-08', 'Admission Open for BA in English', 'Dive into the world of literature and creative writing with our esteemed English Department under the guidance of experienced and dedicated faculty members.', 'https://cub.edu.bd/news_post.php?title=Admission-Open-for-BA-in-English', 'news\\2024-02-08_Admission_Open_for_BA_in_English.jpg'),
(128, '2024-02-08', 'Shape the Future: Join the Department of CSE at Canadian University of Bangladesh', 'Join the dynamic world of technology at Department of CSE of Canadian University of Bangladesh. Experience cutting-edge education, world-class faculty, and exciting opportunities.', 'https://cub.edu.bd/news_post.php?title=Shape-the-Future-Join-the-Department-of-CSE-at-Canadian-University-of-Bangladesh', 'news\\2024-02-08_Shape_the_Future_Join_the_Department_of_CSE_at_Ca.jpg'),
(129, '2024-02-01', 'Unlocking Success: BA in English at Canadian University of Bangladesh', 'Experience exceptional faculty, Canadian-standard curriculum, job placement support, scholarships, state-of-the-art facilities, and vibrant extracurricular activities.', 'https://cub.edu.bd/news_post.php?title=Unlocking-Success-BA-in-English-at-Canadian-University-of-Bangladesh', 'news\\2024-02-01_Unlocking_Success_BA_in_English_at_Canadian_Unive.jpg'),
(130, '2024-02-01', 'Yet another momentous milestone for Canadian University of Bangladesh!', 'Canadian University of Bangladesh and Hypertension Center, Rangpur, Bangladesh, have embarked on a transformative journey with the signing of a Memorandum of Understanding.', 'https://cub.edu.bd/news_post.php?title=Yet-another-momentous-milestone-for-Canadian-University-of-Bangladesh', 'news\\2024-02-01_Yet_another_momentous_milestone_for_Canadian_Unive.jpg'),
(131, '2024-01-31', 'EEE at Canadian University of Bangladesh: Pioneering a Bright Future', 'The Electrical and Electronic Engineering (EEE) Department of Canadian University of Bangladesh (CUB) is among the top choices for a bright career.', 'https://cub.edu.bd/news_post.php?title=EEE-at-Canadian-University-of-Bangladesh-Pioneering-a-Bright-Future', 'news\\2024-01-31_EEE_at_Canadian_University_of_Bangladesh_Pioneeri.jpg'),
(132, '2024-01-29', 'Recent visit to the office of Dr. Shahjahan Mahmood, Chairman and CEO of BSCL', 'On January 28, 2024, a few dignitaries of CUB visited Dr. Shahjahan Mahmood, Chairman and CEO of Bangladesh Satellite Company Limited (BSCL).', 'https://cub.edu.bd/news_post.php?title=Recent-visit-to-the-office-of-Dr-Shahjahan-Mahmood-Chairman-and-CEO-of-BSCL', 'news\\2024-01-29_Recent_visit_to_the_office_of_Dr._Shahjahan_Mahmoo.png'),
(133, '2024-01-28', 'Recent visit to the office of Mr. Hasnaeen Rizvi, CEO of Astha IT', 'On 28 January, 2024, a few dignitaries of the Canadian University of Bangladesh had the privilege of visiting the office of Mr. Hasnaeen Rizvi, CEO of Astha IT.', 'https://cub.edu.bd/news_post.php?title=Recent-visit-to-the-office-of-Mr-Hasnaeen-Rizvi-CEO-of-Astha-IT', 'news\\2024-01-28_Recent_visit_to_the_office_of_Mr._Hasnaeen_Rizvi,_.png'),
(134, '2024-01-25', 'চাকুরির শতভাগ নিশ্চয়তায় মিডিয়া, কমিউনিকেশন এ্যান্ড জার্নালিজম বিভাগে স্নাতক', 'শতভাগ চাকুরির নিশ্চয়তায় স্নাতক শ্রেণিতে ভর্তি নিচ্ছে দেশের প্রথিতযশা বিশ্ববিদ্যালয় কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ-এর মিডিয়া কমিউনিকেশন এ্যান্ড জার্নালিজম (এমসিজে) বিভাগ ।', 'https://cub.edu.bd/news_post.php?title=graduates-in-media-communication-and-journalism-with-100-job-guarantee', 'news\\2024-01-25_চাকুরির_শতভাগ_নিশ্চয়তায়_মিডিয়া,_কমিউনিকেশন_এ্যান্ড.jpg'),
(135, '2024-01-22', 'Strengthening Blue Economy: Joint Collaborative Initiatives between CUB and BIMRAD', 'January 22nd, the Vice-Chancellor (In Charge) and Pro-VC of the Canadian University engaged in a meaningful meeting with Captain M Minhaz Uddin, (H), NPP, psc, BN, DG of BIMRAD.', 'https://cub.edu.bd/news_post.php?title=Strengthening-Blue-Economy-Joint-Collaborative-Initiatives-between-CUB-and-BIMRAD', 'news\\2024-01-22_Strengthening_Blue_Economy_Joint_Collaborative_In.jpg'),
(136, '2024-01-21', 'Admission opens to B.Sc in CSE (Diploma Holders) for spring 2024', 'Admissions are ongoing for Diploma Holders in B.Sc in Computer Science and Engineering (CSE) in spring 2024 at the Canadian University of Bangladesh.', 'https://cub.edu.bd/news_post.php?title=Admission-opens-to-B-Sc-in-CSE-Diploma-Holders-for-spring-2024', 'news\\2024-01-21_Admission_opens_to_B.Sc_in_CSE_(Diploma_Holders)_f.jpg'),
(137, '2024-01-16', 'Strengthening Food Science and AI: Collaborative Efforts of CUB and MIST', 'The Vice-Chancellor (In Charge) and Pro-VC of CUB, along\nwith the Commandant of MIST, held a fruitful meeting on 14th January at 11:30\nam, demonstrating the strength of both institutions.', 'https://cub.edu.bd/news_post.php?title=Strengthening-Food-Science-and-AI-Collaborative-Efforts-of-CUB-and-MIST', 'news\\2024-01-16_Strengthening_Food_Science_and_AI_Collaborative_E.jpg'),
(138, '2024-01-16', 'Strategic collaborations between CUB and BUP', 'Vice Chancellor (In Charge) of CUB Prof. Dr. Gias U Ahsan\nand Vice chancellor of BUP Major Gen. Md. Mahbub-ul-Alam recently discussed\nabout strategic collaborations.', 'https://cub.edu.bd/news_post.php?title=Strategic-collaborations-between-CUB-and-BUP', 'news\\2024-01-16_Strategic_collaborations_between_CUB_and_BUP.jpg'),
(139, '2024-01-16', 'CUB and UNIVERSITY OF LEEDS Research Collaboration', 'Canadian University of Bangladesh and the Department of IB,\nLUBS, UNIVERSITY OF LEEDS have come together for a historic alliance aimed at\nfostering collaborative efforts.', 'https://cub.edu.bd/news_post.php?title=CUB-and-UNIVERSITY-OF-LEEDS-Research-Collaboration', 'news\\2024-01-16_CUB_and_UNIVERSITY_OF_LEEDS_Research_Collaboration.jpg'),
(140, '2024-01-16', 'CUB Vice-Chancellor (In charge) and UGC Chairman (in charge) had a warm discussion', 'Today, Prof. Dr. Gias U Ahsan, the Vice-Chancellor (In\nCharge) of the Canadian University of Bangladesh had a warm discussion with\nProf. Dr. Muhammed Alamgir, UGC Chairman (in charge).', 'https://cub.edu.bd/news_post.php?title=CUB-Vice-Chancellor-In-charge-and-UGC-Chairman-in-charge-had-a-warm-discussion', 'news\\2024-01-16_CUB_Vice-Chancellor_(In_charge)_and_UGC_Chairman_(.jpg'),
(141, '2024-01-16', '‘EduTech Consortium’ at Canadian University of Bangladesh.', 'In pursuit of excellence, innovation, and dynamic collaboration, the Canadian University of Bangladesh proudly introduces the \"EduTech Consortium.\"', 'https://cub.edu.bd/news_post.php?title=EduTech-Consortium-at-Canadian-University-of-Bangladesh', 'news\\2024-01-16_‘EduTech_Consortium’_at_Canadian_University_of_Ban.jpg'),
(142, '2024-01-15', 'Admission opens with special waiver at Canadian University of Bangladesh', 'Offering special waiver on admission fees, Canadian University of Bangladesh is going to arrange a spot admission fair. The ten-day-long fair at the university campus in Pragati Sarani of the capital has been started on 15th January and end on 25th January 2024.', 'https://cub.edu.bd/news_post.php?title=Admission-opens-with-special-waiver-at-Canadian-University-of-Bangladesh-Spring-24', 'news\\2024-01-15_Admission_opens_with_special_waiver_at_Canadian_Un.jpg'),
(143, '2024-01-15', 'কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশে বিশেষ ছাড়ে ভর্তি', 'ভর্তি ফির উপর বিশেষ ছাড়ে ভর্তি মেলা শুরু হয়েছে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশ ক্যাম্পাসে। রাজধানীর প্রগতি সরণিতে বিশ্ববিদ্যালয়ের নিজস্ব ভবনে সোমবার ১৫ জানুয়ারি এই মেলা শুরু হয়েছে, চলবে ২৫ জানুয়ারি পর্যন্ত।', 'https://cub.edu.bd/news_post.php?title=canadian-university-of-bangladesh-special-discount-admission', 'news\\2024-01-15_কানাডিয়ান_ইউনিভার্সিটি_অব_বাংলাদেশে_বিশেষ_ছাড়ে_ভর্.jpg'),
(144, '2024-01-14', 'Admission opens with Special Waiver at CUB', 'The Canadian University of Bangladesh (CUB) is currently hosting its Spring 2024 Admission Fair, which runs from January 15th to January 25th, 2024.', 'https://cub.edu.bd/news_post.php?title=Admission-opens-with-Special-Waiver-at-CUB', 'news\\2024-01-14_Admission_opens_with_Special_Waiver_at_CUB.jpg'),
(145, '2023-12-18', 'Respected Vice Chancellor (In Charge) of CUB interacted with the students', 'Today in the morning, Professor Dr. Gias U Ahsan, the Respected Vice Chancellor (In Charge) of Canadian University of Bangladesh interacted with the students.', 'https://cub.edu.bd/news_post.php?title=Respected-Vice-Chancellor-In-Charge-of-CUB-interacted-with-the-students', 'news\\2023-12-18_Respected_Vice_Chancellor_(In_Charge)_of_CUB_inter.jpg'),
(146, '2023-11-27', 'CUB and Artemis Join Forces with Artemis Biotechnologies in Academic-Industry Partnership', 'The Canadian University of Bangladesh (CUB) and Artemis Biotechnologies have formalized a Memorandum of Understanding (MoU).', 'https://cub.edu.bd/news_post.php?title=CUB-and-Artemis-Join-Forces-with-Artemis-Biotechnologies-in-Academic-Industry-Partnership', 'news\\2023-11-27_CUB_and_Artemis_Join_Forces_with_Artemis_Biotechno.jpg'),
(147, '2023-11-27', 'CUB and Texas A&M University Lab Sign Memorandum of Understanding to Promote Collaboration in Education and Research', 'The CUB and the Texas A&M University Lab have signed a MoU to promote collaboration in the areas of faculty and student exchange, joint research', 'https://cub.edu.bd/news_post.php?title=CUB-and-Texas-A-amp-M-University-Lab-Sign-Memorandum-of-Understanding-to-Promote-Collaboration-in-Education-and-Research', 'news\\2023-11-27_CUB_and_Texas_A&M_University_Lab_Sign_Memorandum_o.jpg'),
(148, '2023-11-21', 'Townhall Meeting of Chairman Held With CUB Faculties and Officers', 'A town hall meeting with Chairman Dr. Chowdhury Nafeez Sarafat where he outlined the university\'s future vision, stressing collaboration and teamwork for achieving goals.', 'https://cub.edu.bd/news_post.php?title=Townhall-Meeting-of-Chairman-Held-With-CUB-Faculties-and-Officers', 'news\\2023-11-21_Townhall_Meeting_of_Chairman_Held_With_CUB_Faculti.jpg'),
(149, '2023-11-19', 'The Annual Debate Competition Successfully Held In Canadian University of Bangladesh', 'The CUB Debating Society (CUBLDS) concluded its annual debate competition, CUBLDS 2nd Inter-Batch Debate Competition 2023, on November 4, 2023.', 'https://cub.edu.bd/news_post.php?title=The-Annual-Debate-Competition-Successfully-Held-In-Canadian-University-of-Bangladesh', 'news\\2023-11-19_The_Annual_Debate_Competition_Successfully_Held_In.jpg'),
(150, '2023-11-05', 'Canadian University Bangladesh\'s Inaugural Startup Carnival Inspires Youth Innovation and Entrepreneurship', 'The Canadian University of Bangladesh\'s inaugural Startup Carnival on November 4, 2023, showcased 100 teams of aspiring entrepreneurs across Bangladesh, with Dhaka Udyan Govt. College emerging as the champion.', 'https://cub.edu.bd/news_post.php?title=Canadian-University-Bangladesh-s-Inaugural-Startup-Carnival-Inspires-Youth-Innovation-and-Entrepreneurship', 'news\\2023-11-05_Canadian_University_Bangladesh\'s_Inaugural_Startup.jpg'),
(151, '2023-10-05', 'Canadian University of Bangladesh (CUB) wins Badminton Championship at North South University Sports Championship 2023.', 'Canadian University of Bangladesh (CUB) won the badminton championship at the North South University Sports Championship 2023 by defeating Independent University of Bangladesh (IUB) in the finals with a score of 2-0. Ashfaq Ahmed Sourav from CUB was the star player, contributing significantly to the team\'s victory.', 'https://cub.edu.bd/news_post.php?title=Canadian-University-of-Bangladesh-CUB-wins-Badminton-Championship-at-North-South-University-Sports-Championship-2023', 'news\\2023-10-05_Canadian_University_of_Bangladesh_(CUB)_wins_Badmi.jpg'),
(152, '2023-09-30', 'Congratulations to the winners of the \"1971 and Bangabandhu\" Essay Writing Competition!', 'It is with great pleasure to extend the heartfelt congratulations to :-Israt Jahan- Elma Hasan and- Md Rizwan Ullah Shuvo', 'https://cub.edu.bd/news_post.php?title=admission-fair-for-fall-semester-2023-begins-at-cub', 'news\\2023-09-30_Congratulations_to_the_winners_of_the_1971_and_Ba.jpg'),
(153, '2023-09-25', 'সিইউবিতে ফল সেমিস্টার - ২০২৩ এর ভর্তি মেলা শুরু', 'শিক্ষার্থীরা ৪,০০০ টাকায় ভর্তি হতে পারবেন, মেলা চলবে ০৬ অক্টোবর পর্যন্ত', 'https://cub.edu.bd/news_post.php?title=সিইউবিতে-ফল-সেমিস্টার-২০২৩এর-ভর্তি-মেলা-শুরু', 'news\\2023-09-25_সিইউবিতে_ফল_সেমিস্টার_-_২০২৩_এর_ভর্তি_মেলা_শুরু.jpg'),
(154, '2023-08-12', 'সিইউবি’র ফল-২০২৩ সেমিস্টারের ভর্তি কার্যক্রম শুরু', 'কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশে (সিইউবি) ফল-২০২৩ সেমিস্টারে ভর্তি কার্যক্রম শুরু হয়েছে। ভর্তিচ্ছুক শিক্ষার্থীরা চাইলে অনলাইনের মাধ্যমেও ভর্তি হতে পারবেন।', 'https://cub.edu.bd/news_post.php?title=cub-results-2023-semester-admission-program-starts', 'news\\2023-08-12_সিইউবি’র_ফল-২০২৩_সেমিস্টারের_ভর্তি_কার্যক্রম_শুরু.jpg'),
(155, '2023-07-27', 'বর্ণিল সাজে কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশে নবীন বরণ অনুষ্ঠিত', 'রাজধানীর প্রগতি সরণি এলাকায় অবস্থিত কানাডিয়ান ইউনিভার্সিটি অব বাংলাদেশের (সিইউবি) নিজস্ব ক্যাম্পাসে গ্রীষ্মকালীন সেমিস্টার-২০২৩ এ ভর্তি হওয়া শিক্ষার্থীদের নবীন বরণ অনুষ্ঠিত হয়েছে।', 'https://cub.edu.bd/news_post.php?title=colorfully-decorated-canadian-university-of-bangladesh-holds-freshman-reception', 'news\\2023-07-27_বর্ণিল_সাজে_কানাডিয়ান_ইউনিভার্সিটি_অব_বাংলাদেশে_নব.jpg'),
(156, '2023-07-27', 'Orientation Program for Summer\'23 Batch at CUB', 'Canadian University of Bangladesh (CUB) held a grand Orientation Program for the newly enrolled students of the Summer\'23 Batch at its city campus in Pragati Sarani area. The event witnessed the enthusiastic participation of fresh minds, eager to embark on their educational journey with CUB.', 'https://cub.edu.bd/news_post.php?title=Orientation-Program-for-Summer-23-Batch-at-CUB', 'news\\2023-07-27_Orientation_Program_for_Summer\'23_Batch_at_CUB.jpg'),
(157, '2023-07-26', 'MBA in Business Intelligence and Data Analytics (BIDA) at Canadian University of Bangladesh', 'MBA in BIDA at CUB is for students to gain data analytics skills for success in digital marketing, fintech, and more. Taught by industry expert Khan Muhammad Saqiful Alam.', 'https://cub.edu.bd/news_post.php?title=MBA-in-Business-Intelligence-and-Data-Analytics-BIDA-at-Canadian-University-of-Bangladesh', 'news\\2023-07-26_MBA_in_Business_Intelligence_and_Data_Analytics_(B.jpeg'),
(158, '2023-07-26', 'Partnership with Padma Bank Limited!', 'Canadian University of Bangladesh (CUB) is proud to announce the signing of an MOU with Padma Bank Limited!', 'https://cub.edu.bd/news_post.php?title=Partnership-with-Padma-Bank-Limited', 'news\\2023-07-26_Partnership_with_Padma_Bank_Limited!.jpg'),
(159, '2023-07-06', 'Chief of Global Economic Monitoring, United Nations (UN), Mr. Hamid Rashid at CUB', 'Mr. Hamid Rashid of United Nations talked about the global economic outlook and its implications for Bangladesh at Canadian University of Bangladesh (CUB)', 'https://cub.edu.bd/news_post.php?title=Chief-of-Global-Economic-Monitoring-United-Nations-UN-Mr-Hamid-Rashid-at-CUB', 'news\\2023-07-06_Chief_of_Global_Economic_Monitoring,_United_Nation.jpg'),
(160, '2023-06-24', 'An insightful workshop on \"A Conversation about Torts\" at CUB', 'CUB is committed to providing quality higher education and job placement.', 'https://cub.edu.bd/news_post.php?title=An-insightful-workshop-on-A-Conversation-about-Torts-at-CUB', 'news\\2023-06-24_An_insightful_workshop_on_A_Conversation_about_To.jpg'),
(161, '2023-06-24', 'CUB Visits Digicon Technology Ltd. to Explore Job Opportunities', 'CUB visited Digicon Technology Ltd. to explore job opportunities and gain insight into the company\'s values, work culture, collaborations, and achievements.', 'https://cub.edu.bd/news_post.php?title=CUB-visited-Digicon-Technology-Ltd-to-explore-job-opportunities-and-gain-insight-into-the-company-s-values-work-culture-collaborations-and-achievement', 'news\\2023-06-24_CUB_Visits_Digicon_Technology_Ltd._to_Explore_Job_.jpg'),
(162, '2023-06-07', 'British Council IELTS Registration Center at Canadian University of Bangladesh', 'CUB has become an authorized IELTS Registration Center for the British Council, bringing encouragement to higher education and making it more comprehensible.', 'https://cub.edu.bd/news_post.php?title=British-Council-IELTS-Registration-Center-at-Canadian-University-of-Bangladesh', 'news\\2023-06-07_British_Council_IELTS_Registration_Center_at_Canad.jpg'),
(163, '2023-06-07', 'NSU-CUB signs MoU for Collaborative Work', 'CUB and NSU have signed an MoU to foster collaborative efforts to enhance the educational experience for students.', 'https://cub.edu.bd/news_post.php?title=NSU-CUB-signs-MoU-for-Collaborative-Work', 'news\\2023-06-07_NSU-CUB_signs_MoU_for_Collaborative_Work.jpg'),
(164, '2023-06-07', 'MoU between Canadian University of Bangladesh and Pune Institute of Business Management', 'Canadian University of Bangladesh (CUB) and Pune Institute of Business Management (PIBM) have embarked on a transformative journey of collaboration and skill development.', 'https://cub.edu.bd/news_post.php?title=MoU-between-Canadian-University-of-Bangladesh-and-Pune-Institute-of-Business-Management', 'news\\2023-06-07_MoU_between_Canadian_University_of_Bangladesh_and_.png');
